import{_ as e,o as t,c as o,ag as r}from"./chunks/framework.QfQ7DfGu.js";const c=JSON.parse('{"title":"2K0300开发板平台","description":"","frontmatter":{"title":"2K0300开发板平台","outline":"deep"},"headers":[],"relativePath":"platform/2k0300.md","filePath":"platform/2k0300.md"}'),E={name:"platform/2k0300.md"};function n(l,a,i,B,p,s){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="_2k0300蜂鸟板" tabindex="-1"><strong>2K0300蜂鸟板</strong> <a class="header-anchor" href="#_2k0300蜂鸟板" aria-label="Permalink to &quot;**2K0300蜂鸟板**&quot;">​</a></h1><p>龙芯LS-2K0300开发板是基于龙芯2K0300处理器的平台产品。2K0300 处理器是基于 LA264 处理器核的多功能 SOC 芯片，采用高集成度设计，提供丰富的功能接口，可满足多场景应用需求，同时支持低功耗技术，能够在低能耗表现下提供高处理性能；开发板所用的主要芯片均采用国产器件，产品可实现较高的国产化率，用户可依据项目情况，进行扩展设计。</p><p>本开发板采用核心板加扩展板的模式设计，核心板上主要使用CPU 2K0300、DDR4 SDRAM、PHY芯片、EMMC、NOR FLASH芯片设计；在底板设计上为用户扩展了丰富的外围接口，比如LCD显示屏、3路SPI接口、4路PWM接口、4路CAN接口、8路AD模拟输入接口、4路I2C接口、1路I2S接口、4路UART接口、SD卡座、网口、USB接口等等。满足工控互联网行业所需的接口要求，以及相关的工作参数满足低功耗设计要求，并能灵活实现系统集成设计，功能扩展等，可广泛应用于国防、电力、交通、医疗、金融、通信、能源、信息家电和物联网等领域。</p><p>点击查看<a href="https://gitcode.com/iot-wan/Loongson-2K0300-99Pi/blob/master/%E5%B9%BF%E4%B8%9C%E9%BE%99%E8%8A%AF%202K300%20%E8%9C%82%E9%B8%9F%E6%9D%BF%E7%94%A8%E6%88%B7%E6%89%8B%E5%86%8C/%E5%B9%BF%E4%B8%9C%E9%BE%99%E8%8A%AF2K0300%E8%9C%82%E9%B8%9F%E6%9D%BF%E5%BF%AB%E9%80%9F%E4%BD%BF%E7%94%A8%E6%8C%87%E5%8D%97-v1.0.240625.pdf" target="_blank" rel="noreferrer">龙芯2K300蜂鸟板用户手册</a>。</p><p>点击查看<a href="https://gitcode.com/iot-wan/Loongson-2K0300-99Pi/blob/master/%E5%B9%BF%E4%B8%9C%E9%BE%99%E8%8A%AF%202K300%20%E8%9C%82%E9%B8%9F%E6%9D%BF%E7%94%A8%E6%88%B7%E6%89%8B%E5%86%8C/%E5%B9%BF%E4%B8%9C%E9%BE%99%E8%8A%AF2K0300%E8%9C%82%E9%B8%9F%E6%9D%BF%E5%BF%AB%E9%80%9F%E4%BD%BF%E7%94%A8%E6%8C%87%E5%8D%97-v1.0.240625.pdf" target="_blank" rel="noreferrer">龙芯2K0300蜂鸟板快速使用指南</a>。</p><h2 id="开发环境" tabindex="-1">开发环境 <a class="header-anchor" href="#开发环境" aria-label="Permalink to &quot;开发环境&quot;">​</a></h2><h3 id="u-boot" tabindex="-1">U-Boot <a class="header-anchor" href="#u-boot" aria-label="Permalink to &quot;U-Boot&quot;">​</a></h3><p>2K0300 提供基于 U-Boot-2022.04 移植开发。</p><p>文档附有详细编译教程。</p><h3 id="linux" tabindex="-1">linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;linux&quot;">​</a></h3><p>2K0300 提供基于 linux-5.10.0 移植开发。</p><p>文档附有详细编译教程。</p><p>上述详细文件，点击[这里]查看(<a href="https://gitee.com/open-loongarch" target="_blank" rel="noreferrer">https://gitee.com/open-loongarch</a>)。</p>',13)])])}const d=e(E,[["render",n]]);export{c as __pageData,d as default};
